import argparse
import json
import sys
import struct
import hashlib
import os

def compute_tag(expr: str, secret: str) -> str:
    combined = f"{expr}{secret}".encode('utf-8')
    return hashlib.sha256(combined).hexdigest()[:32]

def evaluate_expr(expr: str) -> int:
    try:
        return eval(expr)
    except:
        return 0

def add_records(cache_path: str, secret: str):
    records = []
    for line in sys.stdin:
        data = json.loads(line.strip())
        expr = data['expr']
        value = evaluate_expr(expr)
        tag = compute_tag(expr, secret)
        records.append((value, expr.encode('utf-8'), tag.encode('utf-8')))
    with open(cache_path, 'wb') as f:
        for value, expr_bytes, tag_bytes in records:
            f.write(struct.pack('>I', len(expr_bytes)))
            f.write(expr_bytes)
            f.write(tag_bytes)
    for data in records:
        value, _, tag = data
        print(f"{data[1].decode('utf-8').strip()}\t{value}\t{tag.decode('utf-8')}")

def verify_records(cache_path: str, secret: str):
    with open(cache_path, 'rb') as f:
        while True:
            try:
                n_bytes = f.read(4)
                if not n_bytes:
                    break
                expr_len = struct.unpack('>I', n_bytes)[0]
                expr_bytes = f.read(expr_len)
                tag_bytes = f.read(16)
                expr = expr_bytes.decode('utf-8')
                computed_tag = compute_tag(expr, secret)
                if computed_tag.encode('utf-8') == tag_bytes:
                    print(f"{expr}\tOK")
                else:
                    print(f"{expr}\tMISMATCH")
            except:
                break

def main():
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='command', required=True)

    add_parser = subparsers.add_parser('add')
    add_parser.add_argument('cache_path')
    add_parser.add_argument('--secret', required=True)

    verify_parser = subparsers.add_parser('verify')
    verify_parser.add_argument('cache_path')
    verify_parser.add_argument('--secret', required=True)

    args = parser.parse_args()

    if args.command == 'add':
        add_records(args.cache_path, args.secret)
    elif args.command == 'verify':
        verify_records(args.cache_path, args.secret)

if __name__ == '__main__':
    main()

import argparse
import hashlib
import sys
from typing import List, Tuple

def evaluate_expression(expr: str) -> int:
    try:
        return eval(expr)
    except:
        return 0

def compute_tag(expr_bytes: bytes, secret: bytes) -> bytes:
    return hashlib.sha256(expr_bytes + secret).digest()

def add_cache(cache_path: str, secret: str) -> None:
    lines = sys.stdin.read().splitlines()
    for line in lines:
        parts = line.split('\t')
        if len(parts) != 2:
            continue
        id_, expr = parts
        try:
            value = evaluate_expression(expr)
        except:
            value = 0
        expr_bytes = expr.encode('utf-8')
        tag = compute_tag(expr_bytes, secret.encode('utf-8'))
        tag_hex = tag.hex().lower()

        with open(cache_path, 'ab') as f:
            f.write(value.to_bytes(4, 'big'))
            f.write(expr_bytes)
            f.write(tag)

        print(f"{id_}\t{value}\t{tag_hex}")

def read_cache(cache_path: str) -> List[Tuple[int, bytes, bytes]]:
    records = []
    with open(cache_path, 'rb') as f:
        while True:
            try:
                n_bytes = f.read(4)
                if not n_bytes:
                    break
                n = int.from_bytes(n_bytes, 'big')
                expr_bytes = f.read(n)
                tag = f.read(16)
                records.append((n, expr_bytes, tag))
            except:
                break
    return records

def verify_cache(cache_path: str, secret: str) -> None:
    records = read_cache(cache_path)
    for n, expr_bytes, stored_tag in records:
        expr = expr_bytes.decode('utf-8')
        tag = compute_tag(expr_bytes, secret.encode('utf-8'))
        if tag == stored_tag:
            print(f"{expr}\tOK")
        else:
            print(f"{expr}\tMISMATCH")

def main():
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='command', required=True)

    add_parser = subparsers.add_parser('add')
    add_parser.add_argument('CACHE_PATH')
    add_parser.add_argument('--secret', required=True)

    verify_parser = subparsers.add_parser('verify')
    verify_parser.add_argument('CACHE_PATH')
    verify_parser.add_argument('--secret', required=True)

    args = parser.parse_args()

    if args.command == 'add':
        add_cache(args.CACHE_PATH, args.secret)
    elif args.command == 'verify':
        verify_cache(args.CACHE_PATH, args.secret)

if __name__ == '__main__':
    main()

import argparse
import hashlib
import sys
from typing import List, Tuple

def evaluate_expression(expr: str) -> int:
    try:
        return int(eval(expr))
    except:
        return 0

def compute_tag(secret: bytes, expr_bytes: bytes) -> bytes:
    return hashlib.sha256(secret + expr_bytes).digest()

def add_cache(cache_path: str, secret: str) -> None:
    exprs = sys.stdin.read().splitlines()
    for expr in exprs:
        if not expr:
            continue
        result = evaluate_expression(expr)
        expr_bytes = expr.encode('utf-8')
        tag = compute_tag(secret.encode('utf-8'), expr_bytes)
        with open(cache_path, 'ab') as f:
            f.write(result.to_bytes(4, 'big'))
            f.write(len(expr_bytes).to_bytes(4, 'big'))
            f.write(expr_bytes)
            f.write(tag)

def verify_cache(cache_path: str, secret: str) -> None:
    with open(cache_path, 'rb') as f:
        while True:
            try:
                n_bytes = f.read(4)
                if not n_bytes:
                    break
                n = int.from_bytes(n_bytes, 'big')
                len_bytes = f.read(4)
                len_expr = int.from_bytes(len_bytes, 'big')
                expr_bytes = f.read(len_expr)
                stored_tag = f.read(16)
                expr_str = expr_bytes.decode('utf-8')
                computed_tag = compute_tag(secret.encode('utf-8'), expr_bytes)
                if stored_tag == computed_tag:
                    print(f"{expr_str}\tOK")
                else:
                    print(f"{expr_str}\tMISMATCH")
            except:
                break

def main():
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='command', required=True)

    add_parser = subparsers.add_parser('add')
    add_parser.add_argument('CACHE_PATH')
    add_parser.add_argument('--secret', required=True)

    verify_parser = subparsers.add_parser('verify')
    verify_parser.add_argument('CACHE_PATH')
    verify_parser.add_argument('--secret', required=True)

    args = parser.parse_args()

    if args.command == 'add':
        add_cache(args.CACHE_PATH, args.secret)
    elif args.command == 'verify':
        verify_cache(args.CACHE_PATH, args.secret)

if __name__ == '__main__':
    main()
